-- build/fit_shell.lua -- make the warehouse shell match Config.
--
-- The warehouse was generated by one-off command-bar scripts that were not kept, so the
-- geometry lives only in the .rbxl and editing Config moves nothing. This is the start of
-- undoing that: run it and the shell follows Config.WallHeight again.
--
-- It FITS rather than rebuilds -- it resizes and repositions the parts that are already
-- there, keeping their materials, colours and names. That makes it idempotent and safe to
-- re-run, and it cannot lose detail that only exists in the place file.
--
-- Run from the Studio command bar in EDIT mode (geometry changed during a playtest is
-- discarded when you stop):
--
--     loadstring(game:GetService("HttpService")
--         :GetAsync("http://127.0.0.1:8767/fit_shell.lua"))()
--
-- It reads Config.WallHeight by default; pass a number to override without editing Config:
--
--     loadstring(...)(60)
--
-- WHAT IT DOES NOT TOUCH: the rail beams the trolley rides. They sit at gantryHeight,
-- and that number is load-bearing in a way the wall height is not -- SkyArm's shoulder hangs
-- SHOULDER_OFFSET below the carriage and reaches L1 + L2 + GRIP_REACH (about 16.9 studs)
-- downward, so at GantryHeight 18 the jaw just reaches the floor. Raise the rails and the arm
-- can no longer touch the bay floor, which breaks crate delivery. Raising the ROOF is free;
-- raising the RAILS is not.

-- Config is READ FROM SOURCE, not required.
--
-- Studio's Edit datamodel caches required modules for the session and editing a ModuleScript's
-- Source does not invalidate that cache -- so require() here returns whatever Config looked
-- like the first time anything asked, which during a long editing session is stale by hours.
-- It cost a confusing "attempt to perform arithmetic on nil" where the value was plainly
-- sitting in the file. Parsing the source is immune to it, and this script only needs two
-- numbers.
local function configNumber(name, fallback)
	local src = game.ReplicatedStorage:WaitForChild("Config").Source
	local v = src:match("[\r\n]Config%." .. name .. "%s*=%s*(%-?[%d%.]+)")
	return tonumber(v) or fallback
end

local warehouse = workspace:WaitForChild("Warehouse")

-- `tonumber(...)` errors with "missing argument #1" when the chunk is called with no
-- arguments, which is the normal case, so capture the varargs first.
local argv = {...}
local wallHeight = tonumber(argv[1]) or configNumber("WallHeight", 28)
local gantryHeight = configNumber("GantryHeight", 18)
local trussTopGap = 2          -- how far the roof beams hang below the wall top

local report = {}
local function note(...)
	table.insert(report, string.format(...))
end

-- Shell walls: span the floor to the new ceiling.
local shell = warehouse:FindFirstChild("Shell")
if shell then
	for _, p in ipairs(shell:GetChildren()) do
		if p:IsA("BasePart") then
			local before = p.Size.Y
			p.Size = Vector3.new(p.Size.X, wallHeight, p.Size.Z)
			p.Position = Vector3.new(p.Position.X, wallHeight / 2, p.Position.Z)
			note("  %-16s height %.0f -> %.0f, top now %.0f", p.Name, before, p.Size.Y, wallHeight)
		end
	end
else
	note("  no Shell folder")
end

-- Roof trusses: ride just under the new ceiling. The rail beams stay put.
local rails = warehouse:FindFirstChild("SkyRails")
local moved, skipped = 0, {}
if rails then
	for _, p in ipairs(rails:GetChildren()) do
		if p:IsA("BasePart") then
			if p.Name:match("^Truss_") then
				p.Position = Vector3.new(p.Position.X, wallHeight - trussTopGap, p.Position.Z)
				moved += 1
			else
				p.Position = Vector3.new(p.Position.X, gantryHeight, p.Position.Z)
				table.insert(skipped, p.Name)
			end
		end
	end
	note("  %d roof trusses raised to y=%.0f", moved, wallHeight - trussTopGap)
	note("  rails left at GantryHeight %.0f: %s", gantryHeight,
		table.concat(skipped, ", "))
end

note("")
note("  ceiling %.0f, rails %.0f, so %.0f studs of air above the crane",
	wallHeight, gantryHeight, wallHeight - gantryHeight)

print("[fit_shell] shell fitted to Config:\n" .. table.concat(report, "\n"))
return table.concat(report, "\n")
